def glomit(self, target, scope):
    # Fill is typically used within dict specs where it gets called
    # for missing keys. The actual filling logic is handled by
    # _handle_dict in core.py when this specifier is encountered.
    # If fill_spec is a primitive value, return it directly;
    # otherwise try to glom it.
    if isinstance(self.fill_spec, (int, float, str, bool, type(None))):
        return self.fill_spec
    return scope[glom](target, self.fill_spec, scope)

